from PIL import Image
import numpy as np
im = Image.open('barcode.png').convert('RGB')
a = np.array(im).astype(float)
cols = a.mean(axis=0)
# print average color per 20-px chunk (50 chunks) as hex
def hexc(c):
    return '#%02x%02x%02x' % tuple(int(round(x)) for x in c)
for w in [20]:
    print(f'--- {w}px chunks ---')
    for i in range(0, 1000, w):
        c = cols[i:i+w].mean(axis=0)
        print(i, hexc(c))
